UPDATE recipe_translations SET ingredients_json = '[{"name":"400g silken tofu","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Doubanjiang (broad-bean paste)","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tsp Sichuan peppercorns","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"150g ground pork","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2 scallions","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Garlic + ginger","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"Light soy sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"Cornstarch slurry","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]' WHERE recipe_id = 'homepage-mapo' AND locale = 'en';

